"""Build the standalone, offline-capable image research book from audited sources."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'public/image-library'
read = lambda name: json.loads((ROOT / 'research' / f'{name}.json').read_text())
esc = html.escape
generated = read('generation-prompts')
stock = read('stock-sources')

copy = {
    'english-reading': ('01', '영어 · 읽고 이해하는 힘', '책과 단어 카드를 중심으로 읽기·어휘의 의미를 담았습니다.', '영어 교육과정 소개', '초록 천 표지의 펼친 책, Aa 단어 카드와 연필'),
    'math-reasoning': ('02', '수학 · 생각을 쌓는 과정', '격자 노트와 입체 도형으로 개념과 풀이의 관계를 표현했습니다.', '수학 교육과정 소개', '격자 노트 위 삼각자와 정육면체, 초록 삼각기둥'),
    'learning-plan': ('03', '학습관리 · 매일의 작은 기록', '플래너와 인덱스로 계획·복습·피드백의 흐름을 보여줍니다.', '학습관리 소개 또는 상담 자료', '초록 노트 위 펼친 격자 플래너와 색 인덱스'),
    'quiet-study': ('04', '공부의 시간 · 차분한 몰입', '자연광과 넉넉한 여백으로 오래 공부할 수 있는 분위기를 만들었습니다.', '학원 철학 소개 또는 콘텐츠 표지', '햇빛이 드는 나무 책상 위 빈 노트와 초록 책'),
}

cards = []
manifest = {'date': '2026-11-04', 'newAssetCount': 8, 'generated': [], 'stock': [], 'logo': {'path':'assets/extracted/nobase-logo.webp', 'width':628, 'height':390, 'originalSize':[1254,779], 'source':'User-provided website planning DOCX, word/media/image1.png', 'originalPath':'source-assets/library/originals/nobase-logo-original.png'}}
for a in generated['assets']:
    num, title, description, placement, alt = copy[a['id']]
    small, large = a['variants']
    path = f"assets/generated/{a['id']}.webp"
    srcset = f"assets/generated/{a['id']}-800.webp {small['width']}w, {path} {large['width']}w"
    cards.append(f'''<article class="asset-card">
      <a class="image-link" href="{path}" target="_blank" rel="noopener" aria-label="{title} 이미지 크게 보기"><img src="{path}" srcset="{srcset}" sizes="(max-width: 720px) calc(100vw - 40px), (max-width: 1200px) calc((100vw - 80px) / 2), 560px" width="{large['width']}" height="{large['height']}" alt="{alt}" loading="lazy"></a>
      <div class="card-copy"><div class="eyebrow">GENERATED / {num}</div><h3>{title}</h3><p>{description}</p>
      <p class="placement">권장 위치 · {placement}</p><div class="card-bottom"><span>{large['width']} × {large['height']} · {large['bytes']/1024:.0f} KB</span><a href="{path}" download>웹용 파일 저장 ↗</a></div></div>
    </article>''')
    manifest['generated'].append({'id': a['id'], 'title': title, 'recommendedPlacement': placement, 'alt': alt, 'path': path, 'width':large['width'], 'height':large['height'], 'bytes':large['bytes'], 'sourceSha256':a['sourceSha256'], 'type':'AI-generated conceptual still life; not an actual academy photo'})

stock_cards = []
for a in sorted((p for p in stock['photos'] if p['selected']), key=lambda p:p['priority']):
    path = 'assets/stock/' + Path(a['webPath']).name
    stock_cards.append(f'''<article class="stock-card"><a class="image-link" href="{esc(a['photoPage'])}" target="_blank" rel="noopener"><img src="{path}" width="{a['webSize'][0]}" height="{a['webSize'][1]}" alt="{esc(a['altKo'])}" loading="lazy"></a><div class="card-copy"><span class="eyebrow">STOCK / {esc(a['provider'])}</span><h3>{esc(a['creator'])}</h3><p>{esc(a['fit'])}</p><p class="note">{esc(a['caveat'])}</p><div class="card-bottom"><a href="{esc(a['photoPage'])}" target="_blank" rel="noopener">사진 출처 ↗</a><a href="{esc(a['licenseUrl'])}" target="_blank" rel="noopener">사용 조건 ↗</a></div></div></article>''')
    manifest['stock'].append({k:a[k] for k in ['id','creator','provider','photoPage','licenseUrl','recommendedUse','altKo','webSize','webBytes','caveat'] } | {'path':path})

motion_cards = []
for key, title in [('hero-poster','첫 화면 전체 정물'),('book','펼친 책'),('sprout','새싹'),('sprout-closed','새싹 · 닫힌 상태'),('pencil','연필')]:
    motion_cards.append(f'<figure><a href="assets/motion/{key}.webp" target="_blank" rel="noopener"><img src="assets/motion/{key}.webp" alt="{title}" loading="lazy" width="240" height="240"></a><figcaption>{title}</figcaption></figure>')

report = (ROOT / 'research/report-fragment.html').read_text()
